// Extract image URL from the previous node (HTTP node output)
const imageUrl = $input.first().json.choices[0].message.images[0].image_url.url;

async function run() {
  // Fetch the image as raw binary (disable auto-parsing)
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: imageUrl,
    encoding: null, // ensures binary buffer
    returnFullResponse: true, // gives us headers + raw body
  });

  // Determine MIME type from headers (fallback to PNG)
  const mimeType = response.headers['content-type'] || 'image/png';
  const ext = mimeType.split('/')[1] || 'png';
  const fileName = `image-from-chatgpt.${ext}`;

  // Convert binary Buffer to Base64
  const buffer = Buffer.isBuffer(response.body)
    ? response.body
    : Buffer.from(response.body);

  // Return in n8n-compatible binary format
  return {
    json: {
      fileName,
      mimeType,
    },
    binary: {
      data: {
        data: buffer.toString('base64'),
        mimeType,
        fileName,
      },
    },
  };
}

return run();

